def test_voice_render_many_frames_applies_release_and_marks_finished():
    # meridian: unit_id=f5f6aafb5968 requirement=4-1
    voice = audio_logic._Voice("a", 440.0)
    voice.note_off()
    frame_count = voice._release_samples + 1

    rendered = voice.render(frame_count)

    indices = np.arange(frame_count)
    expected_envelope = np.minimum(
        np.minimum(1.0, indices / voice._attack_samples),
        np.maximum(0.0, 1.0 - indices / voice._release_samples),
    )
    expected = (
        np.sin(voice._phase_increment * indices)
        * expected_envelope
        * audio_logic._PER_VOICE_AMPLITUDE
    ).astype(np.float32)
    assert isinstance(rendered, np.ndarray)
    assert rendered.shape == (frame_count,)
    np.testing.assert_allclose(rendered, expected)
    assert rendered[-1] == np.float32(0.0)
    assert voice.finished is True


